mapper.select:
SELECT t.session_id , t.training_type , COALESCE(c.call_title, p.pose_title) AS scenario_title , t.started_at , t.score
AND t.training_type = #{trainingType}
ORDER BY t.started_at DESC, t.session_id DESC LIMIT #{limit}

SELECT t.session_id , t.training_type , q.item_order , q.label , q.stat_label , q.weak_feedback AS feedback , COALESCE(r.score > 0, FALSE) AS passed FROM training_sessions t JOIN call_simulator q ON q.call_scenario_id = t.call_scenario_id LEFT JOIN session_results r ON r.session_id = t.session_id AND r.call_item_id = q.item_id WHERE t.user_id = #{userId} AND t.ended_at IS NOT NULL AND t.training_type = 'CALL119'
AND t.session_id IN #{id}
UNION ALL
SELECT t.session_id , t.training_type , s.step_order , s.label , s.label , s.weak_feedback , COALESCE(JSON_VALUE(r.detail_json, '$.passed') IN ('true', '1'), FALSE) FROM training_sessions t JOIN session_results r ON r.session_id = t.session_id JOIN pose_steps s ON s.pose_step_id = r.pose_step_id WHERE t.user_id = #{userId} AND t.ended_at IS NOT NULL AND t.training_type = 'POSE'
AND t.session_id IN #{id}
ORDER BY session_id, item_order
